<?php
declare(strict_types=1);
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/audit.php';
$user=snc_require_auth(['admin']);$csrfToken=snc_csrf_token();header('Cache-Control: no-store');
function snc_audit_escape(mixed $value): string {return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
$filters=['search'=>'','from'=>'','to'=>'','user'=>'','activity'=>''];$error='';$detailError='';$report=null;$detail=null;$users=[];$started=null;
try {
    $filters=snc_audit_filters($_GET);$pdo=snc_get_db();
    $users=$pdo->query('SELECT id,full_name,username FROM users ORDER BY full_name,id')->fetchAll();
    $started=$pdo->query('SELECT started_at FROM audit_recording_info WHERE id=1')->fetchColumn();
    $page=filter_input(INPUT_GET,'page',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:1;
    $report=snc_audit_report($pdo,$filters,$page);
    if(isset($_GET['source'])||isset($_GET['event_id'])){
        try{
            $source=is_string($_GET['source']??null)?$_GET['source']:'';$eventId=filter_input(INPUT_GET,'event_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;
            $detail=snc_audit_detail($pdo,$source,$eventId);if(!$detail){http_response_code(404);$detailError='Audit record not found.';}
        }catch(InvalidArgumentException $e){http_response_code(400);$detailError=$e->getMessage();}
    }
}catch(InvalidArgumentException $e){http_response_code(400);$error=$e->getMessage();}
catch(Throwable $e){http_response_code(503);$error='Audit Trail is unavailable. Please try again.';}
$listUrl='audit.php?'.http_build_query($filters+['page'=>$report['page']??1]);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Audit Trail | SNC 2018 Café &amp; Resto</title>
<link rel="icon" type="image/svg+xml" href="../assets/images/snc-dreamcatcher-emblem.svg"><link rel="stylesheet" href="../assets/css/snc-tokens.css?v=1.0"><link rel="stylesheet" href="../assets/css/snc-navigation.css?v=1.1"><link rel="stylesheet" href="../assets/css/snc-dashboard.css?v=1.2"><link rel="stylesheet" href="../assets/css/snc-menu.css?v=1.4"><link rel="stylesheet" href="../assets/css/snc-audit.css?v=1.0"><script src="../assets/js/snc-navigation.js?v=1.0" defer></script><script src="../assets/js/snc-audit.js?v=1.0" defer></script></head><body><div class="snc-shell" id="snc-shell"><?php $adminPage='audit';require __DIR__.'/../includes/admin-shell.php'; ?><main class="snc-dashboard snc-audit-workspace">
<section class="snc-dashboard__header"><div><h1 class="snc-dashboard__title">Audit Trail</h1><p class="snc-dashboard__subtitle">Review who did what, when it happened, and the recorded changes.</p></div><a class="snc-menu-button" href="<?= snc_audit_escape($listUrl) ?>">Refresh</a></section>
<section class="snc-card"><form class="snc-menu-filters snc-audit-filters" method="get" action="audit.php"><label>Search activity<input name="search" maxlength="120" value="<?= snc_audit_escape($filters['search']) ?>" placeholder="User or affected record"></label><label>From<input name="from" type="date" value="<?= snc_audit_escape($filters['from']) ?>"></label><label>To<input name="to" type="date" value="<?= snc_audit_escape($filters['to']) ?>"></label><label>User<select name="user"><option value="">All Users</option><option value="unknown"<?= $filters['user']==='unknown'?' selected':'' ?>>Unmatched / removed accounts</option><?php foreach($users as $entry): ?><option value="<?= (int)$entry['id'] ?>"<?= $filters['user']===(string)$entry['id']?' selected':'' ?>><?= snc_audit_escape($entry['full_name'].' ('.$entry['username'].')') ?></option><?php endforeach; ?></select></label><label>Activity type<select name="activity"><option value="">All Activities</option><?php foreach(SNC_AUDIT_ACTIVITIES as $module=>$group): ?><optgroup label="<?= snc_audit_escape($group['label']) ?>"><?php foreach($group['actions'] as $action=>$label): $value=$module.':'.$action; ?><option value="<?= snc_audit_escape($value) ?>"<?= $filters['activity']===$value?' selected':'' ?>><?= snc_audit_escape($label) ?></option><?php endforeach; ?></optgroup><?php endforeach; ?></select></label><div class="snc-menu-actions"><button class="snc-menu-button snc-menu-button--primary" type="submit">Apply Filters</button><a class="snc-menu-button" href="audit.php">Reset</a></div></form><p class="snc-menu-hint">Times are shown in UTC+08:00. Filters apply across all recorded activity.</p></section>
<?php if($error||$detailError): ?><section class="snc-card"><p class="snc-menu-error" role="alert"><?= snc_audit_escape($error?:$detailError) ?></p></section><?php endif; ?>
<?php if($detail): ?><section class="snc-card"><div class="snc-menu-results"><h2>Audit Record Details</h2><a class="snc-menu-button" href="<?= snc_audit_escape($listUrl) ?>">Back to Activity</a></div><h3><?= snc_audit_escape($detail['activity']) ?></h3><dl class="snc-audit-facts"><div><dt>Record</dt><dd><?= snc_audit_escape(strtoupper($detail['source']).'-'.$detail['event_id']) ?></dd></div><div><dt>When</dt><dd><?= snc_audit_escape($detail['occurred_at']) ?></dd></div><div><dt>User / attempted account</dt><dd><?= snc_audit_escape($detail['actor']) ?></dd></div><div><dt>Affected record</dt><dd><?= snc_audit_escape($detail['target_name']) ?></dd></div></dl><div class="snc-table-wrap"><table class="snc-table snc-audit-changes"><thead><tr><th>Field</th><th>Before</th><th>After / recorded details</th></tr></thead><tbody><?php foreach($detail['changes'] as $change): ?><tr><td><?= snc_audit_escape($change['field']) ?></td><td><?= snc_audit_escape($change['before']) ?></td><td><?= snc_audit_escape($change['after']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($detail['order_id']): ?><p><a class="snc-menu-button" href="order.php?order_id=<?= (int)$detail['order_id'] ?>">View Order</a></p><?php endif; ?></section><?php endif; ?>
<?php if($report): ?><section class="snc-card"><div class="snc-menu-results"><h2>Activity Records <span class="snc-menu-count"><?= $report['total'] ?></span></h2><span>Page <?= $report['page'] ?> of <?= $report['pages'] ?></span></div>
<div class="snc-table-wrap" role="region" aria-label="Audit activity" tabindex="0"><table class="snc-table snc-menu-table snc-audit-table"><thead><tr><th>When</th><th>User / Attempted Account</th><th>Activity</th><th>Affected Record</th><th>Details</th></tr></thead><tbody><?php foreach($report['rows'] as $row): ?><tr><td><?= snc_audit_escape((new DateTimeImmutable($row['occurred_at']))->format('M j, Y · g:i A')) ?></td><td><?= snc_audit_escape(snc_audit_actor($row)) ?></td><td><?= snc_audit_escape(snc_audit_activity($row)) ?><span class="snc-audit-secondary"><?= snc_audit_escape(SNC_AUDIT_ACTIVITIES[$row['module']]['label']??'Activity') ?></span></td><td><?= snc_audit_escape($row['target_name']) ?><span class="snc-audit-secondary"><?= snc_audit_escape(strtoupper($row['source']).'-'.$row['event_id']) ?></span></td><td><a class="snc-menu-button" data-audit-details data-source="<?= snc_audit_escape($row['source']) ?>" data-event-id="<?= (int)$row['event_id'] ?>" href="?<?= snc_audit_escape(http_build_query($filters+['page'=>$report['page'],'source'=>$row['source'],'event_id'=>$row['event_id']])) ?>">View Details</a></td></tr><?php endforeach; ?><?php if(!$report['rows']): ?><tr><td colspan="5">No activity matches these filters.</td></tr><?php endif; ?></tbody></table></div>
<nav class="snc-menu-pagination" aria-label="Audit pages"><?php if($report['page']>1): ?><a class="snc-menu-button" href="?<?= snc_audit_escape(http_build_query($filters+['page'=>$report['page']-1])) ?>">Previous</a><?php endif; ?><?php if($report['page']<$report['pages']): ?><a class="snc-menu-button" href="?<?= snc_audit_escape(http_build_query($filters+['page'=>$report['page']+1])) ?>">Next</a><?php endif; ?></nav>
<p class="snc-menu-hint snc-menu-note">Read-only records from authentication, staff changes, and stock movements are included. Detailed menu, recipe, ingredient, order, and kitchen change tracking began <?= $started?snc_audit_escape((new DateTimeImmutable($started))->format('M j, Y · g:i A')):'with this audit trail' ?>. Earlier unrecorded changes are not reconstructed.</p></section><?php endif; ?>
<dialog class="snc-menu-dialog snc-audit-dialog" id="snc-audit-dialog" aria-labelledby="snc-audit-title"><div class="snc-menu-dialog__head"><h2 id="snc-audit-title">Audit Record Details</h2><button class="snc-menu-button" id="snc-audit-close" type="button">Close</button></div><div id="snc-audit-detail-body" aria-live="polite"></div></dialog>
</main></div></div></body></html>
